on conflict (sku) do update set
  categoria_id = excluded.categoria_id,
  nombre = excluded.nombre,
  descripcion_corta = excluded.descripcion_corta,
  descripcion_larga = excluded.descripcion_larga,
  marca = excluded.marca,
  orden = excluded.orden,
  datasheet_url = excluded.datasheet_url,
  imagen_principal = excluded.imagen_principal,
  especificaciones = excluded.especificaciones,
  info_adicional = excluded.info_adicional,
  documentos = excluded.documentos,
  updated_at = now();

-- Precios PVP de la lista 28X (1 de julio de 2026), sin descuento. Solo la columna precio.
update productos p set precio = v.precio, updated_at = now()
from (values
  ('01817', 6.85),
  ('02692', 161.33),
  ('02692.S.1', 21.03),
  ('02963', 66.57),
  ('02974', 158.37),
  ('02974.B', 158.37),
  ('02974.M', 161.53),
  ('02974.N', 182.12),
  ('03981', 56.01),
  ('03982', 83.58),
  ('03983', 70.25),
  ('03985', 102.72),
  ('03986', 111.28),
  ('03989', 107.68),
  ('0K14597.01', 94.53),
  ('03980', 75.69)
) as v(sku, precio)
where p.sku = v.sku;

commit;

-- Comprobación: debe dar 90 productos, 90 con precio y 0 sin precio
select count(*) as productos,
  count(*) filter (where precio > 0) as con_precio,
  count(*) filter (where precio is null or precio = 0) as sin_precio
from productos p join categorias c on c.id = p.categoria_id
where c.slug like 'vimar-iot-%';
